import os
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _extract_lines(blocks: List[Dict[str, Any]]) -> str:
    lines = []
    for block in blocks:
        if block.get("BlockType") == "LINE":
            text = block.get("Text")
            if text:
                lines.append(text)
    return "\n".join(lines)


def _extract_layout(blocks: List[Dict[str, Any]]) -> Dict[str, Any]:
    pages = {}
    for block in blocks:
        block_type = block.get("BlockType")
        page_num = block.get("Page", 1)
        if page_num not in pages:
            pages[page_num] = {"lines": [], "tables": 0, "forms": 0, "words": 0}

        if block_type == "LINE":
            text = block.get("Text")
            if text:
                pages[page_num]["lines"].append(text)
        elif block_type == "TABLE":
            pages[page_num]["tables"] += 1
        elif block_type == "KEY_VALUE_SET":
            entity_types = block.get("EntityTypes", [])
            if any(t in ("KEY", "VALUE") for t in entity_types):
                pages[page_num]["forms"] += 1
        elif block_type == "WORD":
            pages[page_num]["words"] += 1

    return {
        "pages": [
            {
                "page": page_num,
                "text": "\n".join(data["lines"]),
                "table_count": data["tables"],
                "form_count": data["forms"],
                "word_count": data["words"],
            }
            for page_num, data in sorted(pages.items())
        ]
    }


def extract_text_and_layout(image_bytes: bytes, region_name: Optional[str] = None) -> Dict[str, Any]:
    """
    Extract plain text and basic layout information from a scanned document image
    using Amazon Textract DetectDocumentText.
    """
    textract = boto3.client("textract", region_name=region_name or os.getenv("AWS_REGION"))

    try:
        response = textract.detect_document_text(
            Document={"Bytes": image_bytes},
        )
    except (BotoCoreError, ClientError) as e:
        raise RuntimeError(f"Amazon Textract OCR failed: {e}") from e

    blocks = response.get("Blocks", [])
    return {
        "text": _extract_lines(blocks),
        "layout": _extract_layout(blocks),
        "provider": "amazon-textract",
    }
